"""A small TOML reader and writer for the application's local state files.

This handles scalar values, quoted keys, tables, and arrays without needing a
third-party parser. Keeping the serializer here also gives stable, readable
state files.
"""
import json
import re


class ParseError(ValueError):
    pass


class Reader:
    def __init__(self, text):
        self.text = text
        self.i = 0

    def skip(self, newline=True):
        while self.i < len(self.text):
            c = self.text[self.i]
            if c in (' \t\r\n' if newline else ' \t\r'):
                self.i += 1
            elif c == '#':
                n = self.text.find('\n', self.i)
                self.i = len(self.text) if n < 0 else n
                if not newline:
                    break
            else:
                break

    def string(self):
        q = self.text[self.i]
        multi = self.text.startswith(q * 3, self.i)
        delim = q * (3 if multi else 1)
        self.i += len(delim)
        if multi and self.text.startswith('\r\n', self.i):
            self.i += 2
        elif multi and self.text.startswith('\n', self.i):
            self.i += 1
        chars = []
        while self.i < len(self.text):
            if self.text.startswith(delim, self.i):
                self.i += len(delim)
                if multi:
                    for _ in range(2):
                        if self.i < len(self.text) and self.text[self.i] == q:
                            chars.append(q)
                            self.i += 1
                return ''.join(chars)
            c = self.text[self.i]
            self.i += 1
            if c == '\n' and not multi:
                raise ParseError()
            if c == '\\' and q == '"':
                if self.i >= len(self.text):
                    raise ParseError()
                c = self.text[self.i]
                self.i += 1
                if c in 'btnfr"\\':
                    chars.append({'b':'\b','t':'\t','n':'\n','f':'\f','r':'\r','"':'"','\\':'\\'}[c])
                elif c in 'uU':
                    count = 4 if c == 'u' else 8
                    chars.append(chr(int(self.text[self.i:self.i+count], 16)))
                    self.i += count
                elif multi and c in '\n\r':
                    self.skip()
                else:
                    raise ParseError()
            else:
                chars.append(c)
        raise ParseError()

    def key(self):
        self.skip(False)
        if self.i >= len(self.text):
            raise ParseError()
        if self.text[self.i] in '\'"':
            return self.string()
        m = re.match(r'[A-Za-z0-9_-]+', self.text[self.i:])
        if not m:
            raise ParseError()
        self.i += len(m.group())
        return m.group()

    def keys(self):
        out = [self.key()]
        self.skip(False)
        while self.i < len(self.text) and self.text[self.i] == '.':
            self.i += 1
            out.append(self.key())
            self.skip(False)
        return out

    def value(self):
        self.skip()
        if self.i >= len(self.text):
            raise ParseError()
        c = self.text[self.i]
        if c in '\'"':
            return self.string()
        if c == '[':
            self.i += 1
            vals = []
            self.skip()
            while self.i < len(self.text) and self.text[self.i] != ']':
                vals.append(self.value())
                self.skip()
                if self.i < len(self.text) and self.text[self.i] == ',':
                    self.i += 1
                    self.skip()
                elif self.i < len(self.text) and self.text[self.i] != ']':
                    raise ParseError()
            if self.i >= len(self.text):
                raise ParseError()
            self.i += 1
            return vals
        if c == '{':
            self.i += 1
            vals = {}
            self.skip()
            while self.i < len(self.text) and self.text[self.i] != '}':
                k = self.key()
                self.skip()
                if self.text[self.i:self.i+1] != '=':
                    raise ParseError()
                self.i += 1
                vals[k] = self.value()
                self.skip()
                if self.text[self.i:self.i+1] == ',':
                    self.i += 1
                    self.skip()
                elif self.text[self.i:self.i+1] != '}':
                    raise ParseError()
            if self.i >= len(self.text):
                raise ParseError()
            self.i += 1
            return vals
        m = re.match(r'[^\s,\]#}]+', self.text[self.i:])
        if not m:
            raise ParseError()
        val = m.group()
        self.i += len(val)
        if val == 'true':
            return True
        if val == 'false':
            return False
        try:
            return int(val.replace('_', ''), 0) if val.lower().startswith(('0x','0b','0o')) else int(val.replace('_',''))
        except ValueError:
            try:
                return float(val.replace('_', ''))
            except ValueError:
                raise ParseError()

    def read(self):
        result = {}
        table = result
        self.skip()
        while self.i < len(self.text):
            if self.text[self.i] == '[':
                self.i += 1
                ks = self.keys()
                if self.text[self.i:self.i+1] != ']':
                    raise ParseError()
                self.i += 1
                table = result
                for k in ks:
                    table = table.setdefault(k, {})
                    if not isinstance(table, dict):
                        raise ParseError()
            else:
                ks = self.keys()
                if self.text[self.i:self.i+1] != '=':
                    raise ParseError()
                self.i += 1
                val = self.value()
                dest = table
                for k in ks[:-1]:
                    dest = dest.setdefault(k, {})
                if ks[-1] in dest:
                    raise ParseError()
                dest[ks[-1]] = val
            self.skip(False)
            if self.i < len(self.text) and self.text[self.i] != '\n':
                raise ParseError()
            self.skip()
        return result


def loads(text):
    try:
        return Reader(text).read()
    except (ValueError, TypeError, IndexError, AttributeError, KeyError):
        raise ParseError() from None


def quoted(text):
    if not any(ord(c) < 32 and c not in '\t\n' for c in text) and "'''" not in text:
        if '\n' in text:
            return "'''\n" + text + "'''"
        if "'" in text:
            return "'''" + text + "'''"
        return "'" + text + "'"
    return json.dumps(text, ensure_ascii=False)


def key(text):
    if re.fullmatch(r'[A-Za-z0-9_-]+', text):
        return text
    return json.dumps(text, ensure_ascii=False)


def value(v):
    if isinstance(v, str):
        return quoted(v)
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, list):
        return '[' + ', '.join(value(x) for x in v) + ']'
    return str(v)


def dumps(data):
    scalars = []
    tables = []
    for k, v in data.items():
        if isinstance(v, dict):
            tables.append('[' + key(k) + ']\n' + ''.join(key(x)+' = '+value(y)+'\n' for x,y in v.items()))
        elif v is not None:
            scalars.append(key(k) + ' = ' + value(v) + '\n')
    result = ''.join(scalars)
    if tables:
        if result:
            result += '\n'
        result += '\n'.join(tables)
    return result
PY"}

