    scalars = []
    tables = []
    for k, v in data.items():
        if isinstance(v, dict):
            tables.append('[' + key(k) + ']\n' + ''.join(key(x)+' = '+value(y)+'\n' for x,y in v.items()))
        elif v is not None:
