"""Local, Markdown-based note and vault management."""
import errno
import os
import pwd
import shutil
import subprocess
import sys
from pathlib import Path

import cli
import tomldata

BLUE = '\x1b[0;34m'
RED = '\x1b[0;31m'
RESET = '\x1b[0m'
OPTION_PANIC = 'called `Option::unwrap()` on a `None` value'
PATH_ERROR = "couldn't find the path specified"


def blue(s):
    return BLUE + str(s) + RESET


class CommandError(Exception):
    pass


def fail(s):
    raise CommandError(s)


def panic(where, message=OPTION_PANIC):
    sys.stdout.flush()
    sys.stderr.write("\nthread 'main' ("+str(os.getpid())+') panicked at '+where+':\n'+message+'\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n')
    raise SystemExit(101)


def os_description(exc):
    n = exc.errno or errno.EIO
    return os.strerror(n) + ' (os error ' + str(n) + ')'


def undefined(exc):
    fail('undefined error: ' + os_description(exc))


def os_debug(exc):
    kinds = {2:'NotFound',13:'PermissionDenied',17:'AlreadyExists',20:'NotADirectory',
             21:'IsADirectory',22:'InvalidInput',39:'DirectoryNotEmpty',40:'FilesystemLoop'}
    n = exc.errno or errno.EIO
    return 'Os { code: '+str(n)+', kind: '+kinds.get(n,'Uncategorized')+', message: "'+os.strerror(n)+'" }'


def validate_name(name):
    if any(c in name for c in '/\\:*?"<>|'):
        fail('invalid name')


def path_components(path):
    # Like filesystem path components: eliminate redundant slashes and dots,
    # but leave parent-directory components for the OS to resolve.
    absolute = path.startswith('/')
    parts = [p for p in path.split('/') if p not in ('','.')]  
    return ('/' if absolute else '') + '/'.join(parts)


def extension(name):
    pos = name.rfind('.')
    return name[pos+1:] if pos > 0 else None


def stem(name):
    pos = name.rfind('.')
    return name[:pos] if pos > 0 else name


def note_path(folder, name):
    joined = path_components(os.path.join(folder, name))
    last = os.path.basename(joined)
    if last == '..' or not last:
        return joined
    return os.path.join(os.path.dirname(joined), stem(last) + '.md')


def item_path(folder, name, kind):
    return note_path(folder,name) if kind=='note' else os.path.join(folder,name)


def canonical(path):
    try:
        return os.path.realpath(path, strict=True)
    except OSError:
        fail(PATH_ERROR)


def config_dir(variable, default):
    val = os.environ.get(variable, '')
    return val if val.startswith('/') else default


class App:
    def __init__(self):
        home = os.environ.get('HOME')
        if not home:
            home = pwd.getpwuid(os.getuid()).pw_dir
        self.config_path = os.path.join(config_dir('XDG_CONFIG_HOME',os.path.join(home,'.config')),'jot','config')
        self.vaults_path = os.path.join(config_dir('XDG_DATA_HOME',os.path.join(home,'.local','share')),'jot','vaults')
        self.config = self.load(self.config_path, {'editor':'nvim','conflict':True}, 'config')
        self.registry = self.load(self.vaults_path, {'vaults':{}}, 'registry')
        self.vaults = self.registry['vaults']
        self.current = self.registry.get('current')
        if self.current is not None and self.current not in self.vaults:
            panic('src/state/vaults/mod.rs:32:91')

    def save(self,path,data):
        try:
            os.makedirs(os.path.dirname(path),exist_ok=True)
            with open(path,'w',encoding='utf-8',newline='') as f:
                f.write(tomldata.dumps(data))
        except OSError:
            panic('src/traits.rs:33:21', "couldn't store data")

    def load(self,path,default,kind):
        if not os.path.exists(path):
            self.save(path,default)
            return dict(default)
        try:
            with open(path,encoding='utf-8') as f:
                data = tomldata.loads(f.read())
            if kind=='config':
                if type(data.get('editor')) is not str or type(data.get('conflict')) is not bool:
                    raise ValueError()
                return {k:data[k] for k in ('editor','conflict')}
            if kind=='registry':
                if not isinstance(data.get('vaults'),dict) or not all(isinstance(v,str) for v in data['vaults'].values()):
                    raise ValueError()
                if 'current' in data and not isinstance(data['current'],str):
                    raise ValueError()
                return {'current':data['current'],'vaults':data['vaults']} if 'current' in data else {'vaults':data['vaults']}
            if kind=='vault':
                if not isinstance(data.get('folder'),str) or not isinstance(data.get('history'),list):
                    raise ValueError()
                if any(k in data and not isinstance(data[k],str) for k in ('name','location')):
                    raise ValueError()
                return {k:data[k] for k in ('name','location','folder','history') if k in data}
            return data
        except (OSError,UnicodeError,ValueError):
            panic('src/traits.rs:24:21', "couldn't parse data")

    def save_registry(self):
        data = {'current':self.current,'vaults':self.vaults} if self.current is not None else {'vaults':self.vaults}
        self.save(self.vaults_path,data)

    def get_vault(self, name=None):
        if name is None:
            name = self.current
            if name is None:
                fail('not inside a vault')
        root = os.path.join(self.vaults[name],name)
        data = self.load(os.path.join(root,'.jot','data'),{'folder':'','history':[]},'vault')
        return data

    def root(self,data):
        if 'name' not in data:
            panic('src/state/vaults/vault.rs:44:28')
        if 'location' not in data:
            panic('src/state/vaults/vault.rs:48:32')
        return os.path.join(data['location'],data['name'])

    def current_folder(self,data):
        return os.path.join(self.root(data),data['folder'])

    def save_vault(self,data):
        self.save(os.path.join(self.root(data),'.jot','data'),data)

    def check_vault(self,name):
        if name not in self.vaults:
            fail('vault '+name+" doesn't exist")

    def vault_list(self,locations):
        for name,loc in self.vaults.items():
            prefix = '👉 ' + blue(name) if name==self.current else '   '+name
            print(prefix + (' \t '+loc if locations else ''))

    def create(self,kind,name,folder):
        validate_name(name)
        path = item_path(folder,name,kind)
        if os.path.exists(path):
            fail('a '+kind+' named '+name+' already exists in this location')
        try:
            if kind=='note':
                with open(path,'w'):
                    pass
            else:
                os.mkdir(path)
        except OSError as ex:
            if ex.errno==errno.ENOENT:
                fail(PATH_ERROR)
            undefined(ex)

    def create_vault(self,name,location):
        if name in self.vaults:
