            location = self.vaults[name]
            self.rename_item('folder',name,new,location)
            data['name'] = new
            self.save_vault(data)
            del self.vaults[name]
            self.vaults[new] = location
            if self.current==name:
                self.current=new
            self.save_registry()
        else:
            data = self.get_vault()
            self.rename_item(kind,name,new,self.current_folder(data))
        print(kind+' '+blue(name)+' renamed to '+blue(new))

    def move(self,kind,name,new):
        if kind=='vault':
            if not os.path.isabs(new):
                fail("specified path isn't absolute")
            self.check_vault(name)
            data = self.get_vault(name)
            old = self.vaults[name]
            self.move_item('folder',name,old,new)
            location = canonical(new)
            data['location'] = location
            self.save_vault(data)
            self.vaults[name] = location
            self.save_registry()
        else:
            data = self.get_vault()
            old = self.current_folder(data)
            new = canonical(os.path.join(old,new))
            if os.path.commonpath([self.root(data),new]) != path_components(self.root(data)):
                fail('path crosses the bounds of vault')
            self.move_item(kind,name,old,new)
        print(kind+' '+blue(name)+' moved')

    def vmove(self,kind,name,dest):
        if dest not in self.vaults:
            fail('vault '+name+" doesn't exist")
        data = self.get_vault()
        if dest==self.current:
            print(kind+' '+name+' already exists in vault '+dest,end='')
        self.move_item(kind,name,self.current_folder(data),os.path.join(self.vaults[dest],dest))
        print(kind+' '+blue(name)+' moved to vault '+blue(dest))

    def run(self,cmd,args,locations):
        if cmd=='config':
            self.settings(args)
        elif cmd=='vault':
            if not args:
                self.vault_list(locations)
            else:
                self.create_vault(*args)
        elif cmd=='enter':
            self.enter(args[0])
        elif cmd in ('note','folder'):
            data = self.get_vault()
            self.create(cmd,args[0],self.current_folder(data))
            print(cmd+' '+blue(args[0])+' created')
        elif cmd=='chdir':
            self.change_folder(args[0])
        elif cmd=='list':
            self.listing(cli.ALIASES[args[0]] if args else None)
        elif cmd=='open':
            data = self.get_vault()
            name = args[0]
            validate_name(name)
            path = note_path(self.current_folder(data),name)
            if not os.path.exists(path):
                fail('note '+name+' not found')
            self.editor(path)
        elif cmd=='opdir':
            data = self.get_vault()
            try:
                subprocess.run(['xdg-open',self.current_folder(data)])
            except OSError as ex:
                undefined(ex)
        else:
            kind = cli.ALIASES[args[0]]
            if cmd=='remove':
                self.remove(kind,args[1])
            elif cmd=='rename':
                self.rename(kind,args[1],args[2])
            elif cmd=='move':
                self.move(kind,args[1],args[2])
            elif cmd=='vmove':
                self.vmove(kind,args[1],args[2])


def main():
    cmd,args,locations = cli.parse(sys.argv[1:])
    try:
        App().run(cmd,args,locations)
    except CommandError as ex:
        print(RED+'error'+RESET+': '+str(ex))
    except BrokenPipeError:
        pass
